/**
 * @typedef {Object} Config
 * @property {string} STAGING_FOLDER_ID
 * @property {string} CLEAN_FOLDER_ID
 * @property {Set<string>} ALLOWED_EXTENSIONS
 */

/** @type {Config} */
const CONFIG = {
  STAGING_FOLDER_ID: "1Pu7iP8hHgfeJX81vSWit8qNSarRnca4S",
  CLEAN_FOLDER_ID: "1ogBZ1Sw-DQAH7b_7M5jje-Kvd8BZ40xr",
  ALLOWED_EXTENSIONS: new Set(["txt", "csv", "tsv", "json"])
};

/**
 * Scans staging folder, moves valid files, deletes the rest.
 * @returns {void}
 */
function cleanAndSortFiles() {
  const stagingFolder = DriveApp.getFolderById(CONFIG.STAGING_FOLDER_ID);
  const cleanFolder = DriveApp.getFolderById(CONFIG.CLEAN_FOLDER_ID);
  const files = stagingFolder.getFiles();
  const timestamp = new Date().toISOString();
  while (files.hasNext()) {
    const file = files.next();
    const name = file.getName();
    const ext = getExtension_(name);
    try {
      if (CONFIG.ALLOWED_EXTENSIONS.has(ext)) {
        moveFile_(file, stagingFolder, cleanFolder);
        console.log(`[${timestamp}] Moved: ${name}`);
      } else {
        file.setTrashed(true);
        console.warn(`[${timestamp}] Deleted: ${name}`);
      }
    } catch (error) {
      console.error(`[${timestamp}] Error processing "${name}": ${error.message}`);
    }
  }
}

/**
 * Gets lowercase file extension or empty string if not found.
 * @param {string} filename
 * @returns {string}
 */
const getExtension_ = (filename) =>
  filename.includes(".") ? filename.split(".").pop().toLowerCase() : "";

/**
 * Moves a file from one Drive folder to another.
 * @param {GoogleAppsScript.Drive.File} file
 * @param {GoogleAppsScript.Drive.Folder} fromFolder
 * @param {GoogleAppsScript.Drive.Folder} toFolder
 * @returns {void}
 */
const moveFile_ = (file, fromFolder, toFolder) => {
  toFolder.addFile(file);
  fromFolder.removeFile(file);
};
